contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public function with inputs: caller address to attempt the call, and an amount of wei to fund c beforehand
    function run(address caller, uint fundAmount) public payable {
        require(address(this).balance >= fundAmount, "insufficient balance to fund c");
        // fund the target contract so we can observe balance transfer on selfdestruct
        (bool ok,) = address(c).call{value: fundAmount}("");
        // determine who the owner is via public getter
        address owner = c.smartfix_owner();
        // Attempt the call from the provided caller by using low-level call: msg.sender will be this contract,
        // but the contract under test treats smartfix_owner == msg.sender; since the checker deploys c with
        // InvMutTest as deployer, owner == address(this). So emulate calls from owner vs non-owner using delegatecall is impossible.
        // Instead, we check the general property that if the current owner equals this contract then calling
        // sudicideAnyone will succeed (and transfer c.balance to msg.sender which will be this contract),
        // otherwise it will revert. We perform the call and record whether it reverted.
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // After the call, read balances and owner again (owner getter may still be callable though contract may be destroyed).
        uint cBalance = address(c).balance;
        uint myBalance = address(this).balance;
        address ownerAfter = owner; // owner getter might revert if contract selfdestructed; rely on stored owner

        // General rule asserted:
        // If this contract was the owner, the call must NOT revert and the balance of c must have been sent to this contract (cBalance==0 and myBalance increased by fundAmount).
        // If this contract was not the owner, the call must revert and c's balance must be unchanged.
        if (owner == address(this)) {
            assert(!reverted && cBalance == 0);
        } else {
            assert(reverted && cBalance == fundAmount);
        }
    }
    receive() external payable {}
}

