contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 sendAmount) public payable {
        require(true);
        // ensure this contract has enough balance if it will forward Ether
        if (sendAmount > 0) {
            require(address(this).balance >= sendAmount);
        }

        // Read the owner and balance before the call
        address ownerBefore = c.smartfix_owner();
        uint256 balBefore = address(c).balance;

        // Perform the call as this contract (the deployer of c / msg.sender for c calls)
        bool reverted;
        // we want to simulate calling sudicideAnyone from either owner or non-owner.
        // If caller equals ownerBefore we call directly (this contract is the deployer and likely owner),
        // otherwise we attempt a call via low-level call encoding to simulate other address —
        // but per constraints msg.sender for calls on c will always be this contract (InvMutTest),
        // so we use the `caller` input only in the assertion to distinguish intended case.
        // Call c.sudicideAnyone and catch revert
        try c.sudicideAnyone{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balance after
        uint256 balAfter = address(c).balance;

        // General rule: if the caller (the intended caller) equals the recorded owner, the call must not revert
        // and c's balance may decrease (due to selfdestruct) — but if the intended caller is not the owner,
        // the call must revert and c's balance must remain unchanged.
        // Because actual msg.sender is this contract, we compare the intended caller to ownerBefore.
        assert( (caller == ownerBefore && reverted == false) || (caller != ownerBefore && reverted == true && balAfter == balBefore) );
    }
    receive() external payable {}
}

